<?php
require_once __DIR__.'/includes/bootstrap.php';$pdo=db();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Event not found.');}
$s=$pdo->prepare("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='registered') AS registered_count FROM events e WHERE e.id=? AND (e.status='published' OR e.created_by=?)");$s->execute([$id,user()['id']??0]);$ev=$s->fetch();if(!$ev){http_response_code(404);exit('Event not found.');}
$isReg=false;if(user()){$s=$pdo->prepare("SELECT status FROM registrations WHERE user_id=? AND event_id=?");$s->execute([user()['id'],$id]);$isReg=$s->fetchColumn()==='registered';}
$cap=(int)$ev['capacity'];$count=(int)$ev['registered_count'];$full=$count>=$cap;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();login_required();if(user()['role']!=='student'){flash('Only student accounts can register.');go('event.php?id='.$id);}if($ev['status']!=='published'||strtotime($ev['event_date'])<time()) {flash('Registration is closed.');go('event.php?id='.$id);}if($isReg){flash('You are already registered.');go('event.php?id='.$id);}try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT capacity FROM events WHERE id=? FOR UPDATE');$lock->execute([$id]);$currentCap=(int)$lock->fetchColumn();$cnt=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='registered'");$cnt->execute([$id]);if((int)$cnt->fetchColumn()>=$currentCap){$pdo->rollBack();flash('This event is full.');go('event.php?id='.$id);}$old=$pdo->prepare('SELECT id FROM registrations WHERE user_id=? AND event_id=?');$old->execute([user()['id'],$id]);$oldId=$old->fetchColumn();if($oldId){$up=$pdo->prepare("UPDATE registrations SET status='registered',registered_at=CURRENT_TIMESTAMP WHERE id=?");$up->execute([$oldId]);}else{$in=$pdo->prepare('INSERT INTO registrations(user_id,event_id) VALUES(?,?)');$in->execute([user()['id'],$id]);}$pdo->commit();flash('Registration successful.');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('Could not register. Please try again.');}go('event.php?id='.$id);}
$pageTitle=$ev['title'];require __DIR__.'/includes/header.php';?><p><a href="index.php">← All events</a></p><section class="hero mb-4"><span class="badge text-bg-light"><?=e($ev['category'])?></span><h1 class="display-5 mt-3"><?=e($ev['title'])?></h1><p class="lead mb-0"><?=e($ev['description'])?></p></section><div class="row g-4"><div class="col-lg-8"><section class="panel"><h2 class="h5 fw-bold">Event details</h2><p class="mt-3"><strong>Date and time</strong><br><?=e(date('l, d F Y · h:i A',strtotime($ev['event_date'])))?></p><p><strong>Venue</strong><br><?=e($ev['venue'])?></p><p><strong>Seats</strong><br><?=$count?> / <?=$cap?> registered</p></section></div><div class="col-lg-4"><section class="panel"><h2 class="h5 fw-bold">Your registration</h2><?php if($isReg):?><div class="alert alert-success mt-3">You're registered.</div><a href="my-registrations.php">View my registrations</a><?php elseif(!$full&&strtotime($ev['event_date'])>time()&&$ev['status']==='published'):?><?php if(!user()):?><a class="btn btn-primary w-100 mt-3" href="login.php">Sign in to register</a><?php elseif(user()['role']==='student'):?><form method="post" class="mt-3"><input type="hidden" name="csrf_token" value="<?=e(token())?>"><button class="btn btn-primary w-100">Register for event</button></form><?php else:?><p class="text-secondary">Admin accounts cannot register as students.</p><?php endif;?><?php else:?><p class="text-secondary mt-3">Registration is closed or event is full.</p><?php endif;?></section></div></div><?php require __DIR__.'/includes/footer.php';?>